void parity(){
 size_t golden_index=0;
 for(auto c:std::vector<std::array<int64_t,3>>{{1,1,3},{3,1,3},{7,1,3},{1001,10,300},{19,3,7},{1000001,1000000,1000000},{1000002,1000000,1000000},{1000003,1000000,1000000}}){reset();expected_plan=ss::sliding_window_plan(c[0],c[1],c[2]);require(expected_plan.size()==frozen_plan[golden_index].size(),"frozen plan count");for(size_t k=0;k<expected_plan.size();++k)require(same(expected_plan[k],frozen_plan[golden_index][k]),"pre-edit exact frozen descriptor");++golden_index;auto null=ss::owned_window_plan(c[0],c[1],c[2],{});auto actual=ss::owned_window_plan(c[0],c[1],c[2],current);require(actual.size()==expected_plan.size()&&null.size()==actual.size(),"plan length parity");for(size_t i=0;i<actual.size();++i)require(same(actual[i],expected_plan[i])&&same(null[i],expected_plan[i]),"exact descriptor fields");require(!bad,"actual descriptor observer values");++fixtures;}
 // Independently enumerated short/exact/adjusted-start golden descriptors.
 reset();expected_plan=ss::sliding_window_plan(7,1,3);auto p=ss::sliding_window_plan(7,1,3,current);require(p.size()==5&&p[0].start_sample==0&&p[1].start_sample==1&&p[4].start_sample==4&&p[4].end_sample==7&&p[0].accept_end==1&&p[4].accept_start==4&&!p[4].generation_stop,"manual overlap golden");++fixtures;
 reset();expected_plan=ss::sliding_window_plan(1000,1,300);auto clamped=ss::owned_window_plan(1000,1,300,current);require(clamped.size()==8&&clamped[1].start==100&&clamped[0].accept_end==200&&clamped[0].generation_stop==std::optional<double>{200},"independent overlap200 lookahead100 clamps");for(size_t i=0;i<clamped.size();++i)require(same(clamped[i],expected_plan[i]),"clamped legacy parity");++fixtures;
 auto x=input(),copy=x;for(int n:{0,1,255,256,257,513})for(int start:{0,17,1025}){reset();expected_slice=ss::slice_window_audio(x,start,n);auto y=ss::acquire_window_before_mel(x,start,n,current);bits(y,expected_slice);bits(ss::acquire_window_before_mel(x,start,n,{}),expected_slice);for(size_t j=0;j<y.size();++j){float expected=start+int(j)<int(x.size())?x[start+j]:0.F;require(std::memcmp(&y[j],&expected,sizeof(float))==0,"independent source offset and positive zero padding");}require(!bad&&downstream==2,"shared actual boundary successful entry");require(trace.size()>=5&&trace[trace.size()-5]==1&&trace[trace.size()-4]==2&&trace[trace.size()-3]==3&&trace[trace.size()-2]==2&&trace.back()==3,"W8-W9-W10 publication phase trace");bits(x,copy);++fixtures;}
}
void cancellation(){auto x=input();expected_plan=ss::sliding_window_plan(200,1,3);expected_slice=ss::slice_window_audio(x,17,513);
 for(int stage:{4,0,5,1,2})for(size_t at:(stage==5?std::vector<size_t>{256,512,513}:std::vector<size_t>{1})){reset();arm=stage;trigger=at;bool caught=false;try{if(stage==4||stage==0)(void)ss::owned_window_plan(200,1,3,current);else(void)ss::acquire_window_before_mel(x,17,513,current);}catch(const engine::runtime::RunCancelled&){caught=true;}require(caught&&downstream==0&&active==0&&!bad,"W11 cancelled absent output downstream zero settled");if(stage==4)require(descriptors>0&&descriptors<expected_plan.size(),"descriptor polling actual early work");if(stage==5){require(copy_units==at,"copy polling final-short/full tile bound");require(stage_counts[1]==0,"stopped final short copy never enters publish phase");}if(stage==1)require(stage_counts[2]==0,"slice publication stop precedes before-mel");size_t stopped_events=events;require(events==stopped_events,"no progress after return");auto old=current;reset();auto b=ss::acquire_window_before_mel(x,17,513,current);bits(b,expected_slice);require(old->cancelled()&&!current->cancelled(),"fresh B independent sticky state");fixtures+=2;}
 reset();arm=5;bool partial_caught=false;try{(void)ss::slice_window_audio(x,17,513,current);}catch(const engine::runtime::RunCancelled&){partial_caught=true;}require(partial_caught&&copy_units==256,"direct slice cannot return partial successful tensor");++fixtures;
 reset();current->cancel();bool caught=false;try{ss::owned_window_plan(200,1,3,current);}catch(const engine::runtime::RunCancelled&){caught=true;}require(caught&&descriptors==0,"W2 prestop plan");caught=false;try{ss::acquire_window_before_mel(x,17,513,current);}catch(const engine::runtime::RunCancelled&){caught=true;}require(caught&&copy_units==0&&downstream==0,"W2 prestop slice");fixtures+=2;
}
void validation(){auto x=input();for(bool stopped:{false,true})for(int kind=0;kind<7;++kind){reset();if(stopped)current->cancel();bool ordinary=false;try{if(kind==0)ss::owned_window_plan(0,1,3,current);if(kind==1)ss::owned_window_plan(3,0,3,current);if(kind==2)ss::owned_window_plan(INT64_MAX,1,3,current);if(kind==3)ss::acquire_window_before_mel(x,-1,3,current);if(kind==4)ss::acquire_window_before_mel(x,1026,3,current);if(kind==5)ss::acquire_window_before_mel(x,0,-1,current);if(kind==6)ss::acquire_window_before_mel(x,0,INT64_MAX,current);}catch(const engine::runtime::RunCancelled&){ordinary=false;}catch(const std::runtime_error&e){std::string message=e.what();ordinary=message.find("SheetSage2 ")==0;}require(ordinary&&copy_units==0&&descriptors==0,"W1 ordinary validation precedence over stop");++fixtures;}reset();expected_slice=ss::slice_window_audio(x,17,513);bits(ss::acquire_window_before_mel(x,17,513,current),expected_slice);++fixtures;}
void external(){auto x=input();expected_plan=ss::sliding_window_plan(200,1,3);expected_slice=ss::slice_window_audio(x,17,513);
 for(int stage:{4,0,5,1,2})for(size_t at:(stage==5?std::vector<size_t>{256,512,513}:std::vector<size_t>{1})){reset();arm=stage;trigger=at;gate=true;bool caught=false;std::thread owner([&]{try{if(stage==4||stage==0)ss::owned_window_plan(200,1,3,current);else ss::acquire_window_before_mel(x,17,513,current);}catch(const engine::runtime::RunCancelled&){caught=true;}returned=true;cv.notify_all();});bool reached=false,early=false;{std::unique_lock<std::mutex>l(mutex);reached=cv.wait_for(l,std::chrono::seconds(2),[]{return entered.load()||returned.load();})&&entered;early=returned;current->cancel();release_gate=true;cv.notify_all();}owner.join();require(reached&&!early&&!expired&&caught&&active==0&&downstream==0,"external stop cannot translate before gated observer settlement");++fixtures;}
 reset();auto actual_a=current;auto a=ss::acquire_window_before_mel(x,17,513,actual_a);require(!actual_a->cancelled(),"completed A clear");reset();auto actual_b=current;arm=5;gate=true;std::vector<float>b;std::thread owner([&]{b=ss::acquire_window_before_mel(x,17,513,actual_b);returned=true;cv.notify_all();});bool reached=false;{std::unique_lock<std::mutex>l(mutex);reached=cv.wait_for(l,std::chrono::seconds(2),[]{return entered.load()||returned.load();})&&entered;if(reached)actual_a->cancel();release_gate=true;cv.notify_all();}owner.join();require(reached&&actual_a->cancelled()&&!actual_b->cancelled()&&actual_a!=actual_b,"W13 actual former A handle transitions while B copies");bits(a,b);++fixtures;
}
