namespace engine::models::sheetsage { namespace { namespace window_testing {
void descriptor(const SheetSage2Window&w)noexcept{if(!expected_plan.empty()&&(size_t(w.index)>=expected_plan.size()||!same(w,expected_plan[size_t(w.index)])))bad=true;++descriptors;hit(4,descriptors);}
void copied(const float*out,size_t begin,size_t count)noexcept{if(count==0||count>256)bad=true;for(size_t j=begin;j<begin+count;++j)if(j>=expected_slice.size()||std::memcmp(&out[j],&expected_slice[j],sizeof(float)))bad=true;copy_units+=count;hit(5,copy_units);}
void stage(int value)noexcept{++stage_counts[value];if(value==3)++downstream;hit(value,1);}
}}}
